arguments.new_str:
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketClassifierService>();

// Train model at startup
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

var data = mlContext.Data.LoadFromTextFile<TicketInput>(
    dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

var pipeline = mlContext.Transforms.Conversion
    .MapValueToKey("Label", nameof(TicketInput.Category))
    .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
    .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
    .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
    .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

var crossValResults = mlContext.MulticlassClassification.CrossValidate(data, pipeline, numberOfFolds: 3, labelColumnName: "Label");

var model = pipeline.Fit(data);
mlContext.Model.Save(model, data.Schema, modelPath);

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

var avgMicro = crossValResults.Average(r => r.Metrics.MicroAccuracy);
var avgMacro = crossValResults.Average(r => r.Metrics.MacroAccuracy);
var avgLogLoss = crossValResults.Average(r => r.Metrics.LogLoss);
app.Logger.LogInformation(
    "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
    avgMicro, avgMacro, avgLogLoss);

app.MapControllers();
app.Run();

